import { createContext, useContext } from "solid-js";
import { createStore } from "solid-js/store";

export interface EndGameData {
	playerId: PlayerId;
	leader: string;
	leaderName: string;
	leaderQuote: string;
	victoryClassType: string;
	victoryName: string;
	victoryDescription: string;
	victoryIconUrl: string;
	victoryBgUrl: string;
	leaderQuoteAudioKey: string;
	isDefeated: boolean;
	movieType: string;
	victoryTab: string;
	isAlive: boolean;
	victorySound: string;
	allowOneMoreTurn: boolean;
	showNextTurnButton: boolean;
}

export interface EndGameContextModel {
	endgameData: EndGameData;
}

enum VictoryScreenTabs {
	Military = "military",
	Science = "scientific",
	Culture = "cultural",
	Economic = "economic",
	Default = "",
}

const GENERIC_WIN_VICTORY_BG = "url('blp:endScreen_banner_victory.png')";
export function createEndGameContextModel() {
	function getVictoryData(): EndGameData {
		const playerList: PlayerLibrary[] = Players.getEverAlive();
		const localPlayerID: PlayerId = GameContext.localPlayerID;
		const localPlayer: PlayerLibrary = playerList[localPlayerID];
		const args = {};
		const allowedOneMoreTurn =
			Game.PlayerOperations.canStart(GameContext.localPlayerID, PlayerOperationTypes.EXTEND_GAME, args, false)
				.Success && !Configuration.getGame().isAnyMultiplayer;
		const endgameData: EndGameData = {
			playerId: -1,
			leader: "",
			leaderName: "",
			leaderQuote: "",
			leaderQuoteAudioKey: "",
			victoryClassType: "",
			victoryName: "",
			victoryDescription: "",
			victoryIconUrl: "",
			victoryBgUrl: GENERIC_WIN_VICTORY_BG,
			movieType: "",
			isDefeated: false,
			victoryTab: "",
			isAlive: true,
			victorySound: "",
			allowOneMoreTurn: allowedOneMoreTurn,
			showNextTurnButton: false, // will be set to the correct value below
		};

		if (localPlayer) {
			const leaderDef: LeaderDefinition | null = GameInfo.Leaders.lookup(localPlayer.leaderType);
			// TODO update a better way in dealing with alternate leader versions
			// This is to take care of the few leaders that have alternate version
			const leader = leaderDef?.LeaderType.replace("_ALT", "") || "";
			endgameData.playerId = localPlayerID;
			endgameData.leader = leader;
			endgameData.leaderName = Locale.compose(localPlayer.leaderName);
			//TODO update as to not concatenate the loc key
			endgameData.leaderQuote = `LOC_VICTORY_${leader}`;
			endgameData.leaderQuoteAudioKey = `VICTORY_${leader}`;
		}

		const victoryManager: VictoryManagerLibrary = Game.VictoryManager;
		const claimedVictories: VictoryManagerLibrary_VictoryInfo[] = victoryManager.getVictories();
		const victory = claimedVictories.find((v) => v.team == localPlayer.team && v.place >= 1);
		if (victory) {
			const definition: VictoryDefinition | null = GameInfo.Victories.lookup(victory.victory);

			if (definition) {
				const victoryType = definition.VictoryClassType;
				const victoryDesctiption = definition.Description;
				endgameData.victoryName = getVictoryLoc(victoryType);
				endgameData.victoryClassType = victoryType;
				endgameData.victoryDescription = victoryDesctiption || "";
				endgameData.victoryBgUrl = UI.getIconCSS(victoryType, "BACKGROUND");
				endgameData.victoryIconUrl = UI.getIconCSS(victoryType, "BADGE");
				endgameData.movieType = `MOVIE_VICTORY_${endgameData.leader}`;
				endgameData.victoryTab = getVictoryScreenTab(victoryType);
				endgameData.victorySound = definition.VictorySound || "";
			}
		} else {
			const defeatType = victoryManager.getLatestPlayerDefeat(localPlayerID);
			const defeatDefinition = GameInfo.Defeats.lookup(defeatType);
			if (defeatDefinition?.DefeatType !== DefeatTypes.NO_DEFEAT) {
				endgameData.victoryName = getVictoryLoc("VICTORY_CLASS_DEFEAT");
				endgameData.victoryBgUrl = UI.getIconCSS("VICTORY_CLASS_DEFEAT", "BACKGROUND");
				endgameData.movieType = chooseDefeatMovie(defeatDefinition?.DefeatType || "", localPlayer);
				endgameData.isDefeated = true;
				endgameData.isAlive = localPlayer.isAlive;
				endgameData.victorySound = "Victory_Defeat";
				endgameData.allowOneMoreTurn = allowOneMoreTurn(defeatDefinition);
				endgameData.showNextTurnButton = Configuration.getGame().isHotseat && Players.getNumAliveHumans() > 0;
			}
		}
		return endgameData;
	}

	function getVictoryLoc(victoryType: string): string {
		switch (victoryType) {
			case "VICTORY_CLASS_CULTURE":
				return Locale.compose("LOC_VICTORY_CULTURE_NAME");
			case "VICTORY_CLASS_ECONOMIC":
				return Locale.compose("LOC_VICTORY_ECONMIC_NAME");
			case "VICTORY_CLASS_MILITARY":
				return Locale.compose("LOC_VICTORY_MILITARY_NAME");
			case "VICTORY_CLASS_SCIENCE":
				return Locale.compose("LOC_VICTORY_SCIENCE_NAME");
			case "VICTORY_CLASS_DOMINATION":
				return Locale.compose("LOC_VICTORY_DOMINATION_NAME");
			case "VICTORY_CLASS_DEFEAT":
				return Locale.compose("LOC_VICTORY_DEFEAT_NAME");
			default:
				return Locale.compose("LOC_VICTORY_SCORE_VICTORY_NAME");
		}
	}

	function getVictoryScreenTab(victoryType: string): string {
		switch (victoryType) {
			case "VICTORY_CLASS_CULTURE":
				return VictoryScreenTabs.Culture as string;
			case "VICTORY_CLASS_ECONOMIC":
				return VictoryScreenTabs.Economic as string;
			case "VICTORY_CLASS_MILITARY":
			case "VICTORY_CLASS_DOMINATION":
				return VictoryScreenTabs.Military as string;
			case "VICTORY_CLASS_SCIENCE":
				return VictoryScreenTabs.Science as string;
			default:
				return VictoryScreenTabs.Default as string;
		}
	}

	function allowOneMoreTurn(defeatDefinition: DefeatDefinition | null) {
		const args = {};
		const result = Game.PlayerOperations.canStart(
			GameContext.localPlayerID,
			PlayerOperationTypes.EXTEND_GAME,
			args,
			false,
		);
		if (Configuration.getGame().isAnyMultiplayer) return false;
		else if (result) return result.Success;
		else if (!defeatDefinition) return true;
		else if (defeatDefinition) return defeatDefinition.AllowOneMoreTurn;
		else return true;
	}

	function chooseDefeatMovie(defeatType: DefeatType, player: PlayerLibrary): string {
		const defeatTypeToUse = defeatType ? defeatType : "DEFEAT_DEFAULT";
		const civilizationDefinition = GameInfo.Civilizations.lookup(player.civilizationType);
		if (!civilizationDefinition) {
			console.error(`screen-endgame: Could not find definition for player leader - ${player.civilizationType}.`);
			return "";
		}

		// Use the default age defeats
		const endGameMovies = GameInfo.EndGameMovies.filter((egm) => {
			if (!egm.CivilizationType && egm.DefeatType && egm.DefeatType == defeatTypeToUse) {
				return true;
			} else if (
				egm.CivilizationType &&
				egm.CivilizationType == civilizationDefinition.CivilizationType &&
				egm.DefeatType &&
				egm.DefeatType == defeatTypeToUse
			) {
				return true;
			} else {
				return false;
			}
		});
		const currentAge = GameInfo.Ages.lookup(Game.age);
		if (civilizationDefinition.ApexAge != currentAge?.AgeType) {
			// Apex Age defeat has higher priority- if a civ is not in their apex, we want the basic defeat of the age. The one with the least priority
			endGameMovies.sort((a: EndGameMovieDefinition, b: EndGameMovieDefinition) => {
				return a.Priority - b.Priority;
			});
		} else {
			// Sort desc by priority!
			endGameMovies.sort((a: EndGameMovieDefinition, b: EndGameMovieDefinition) => {
				return b.Priority - a.Priority;
			});
		}

		const movieToShow = endGameMovies[0];
		if (movieToShow) {
			return movieToShow.MovieType;
		} else return "";
	}

	const [endgameData, setEndgameData] = createStore<EndGameData>(getVictoryData());

	function refreshEndgameData() {
		setEndgameData(getVictoryData());
	}

	return {
		endgameData,
		refreshEndgameData,
	};
}

export const EndGameScreenContext = createContext<EndGameContextModel>();

export function useEndGameContext() {
	const context = useContext(EndGameScreenContext);

	if (!context) {
		throw new Error("Unable to get endgame screen context!");
	}

	return context;
}
